// Einmaliger QA-Re-Check (2026-09-09): guard_symbol_drift bei diesen 2 Vorgaengen
// ('Sparschwein', 'Rathaus im Hintergrund') steht NICHT mehr in der aktuellen
// forbiddenSymbolRe-Blockliste des QA-Agenten (nur noch waage/aktenberg/nebel/monster/
// hai/haie/marionette(n)/theater(buehne)/clown(s)/maskottchen) - die alten Verdikte vom
// 01.08./27.07. sind vermutlich ein Artefakt einer damals strengeren Version. Re-Check
// mit dem VORHANDENEN Konzept (keine Neugenerierung), bevor irgendetwas Bild-Teures
// angestossen wird. Siehe allris_topic_error_final_qapassed_root_cause_2026-09-09.
const TARGETS = ["vol_10582","vol_10721"];
return TARGETS.map(vorgangKey => ({ json: { vorgangKey } }));

const j = $json;
return { json: {
  qaStage: 'visual_prompt',
  vorgangKey: j.vorgangKey,
  vorgangsnummer: j.vorgangsnummer,
  title: j.title,
  summaryText: j.summaryText,
  combinedText: j.combinedText,
  analysisJson: j.analysisJson,
  contentJson: j.contentJson,
  visualJson: j.visualJson
} };

const row = $json;
const qa = $('QA-Agent erneut ausfuehren').item.json;
const passed = qa.passed === true;
return { json: {
  ...row,
  qaPassed: passed,
  qaCheckedAt: qa.checkedAt || new Date().toISOString(),
  qaVerdictJson: JSON.stringify(qa),
  imageForceReset: passed ? true : !!row.imageForceReset,
  _qaRecheckPassed: passed
} };
